	@Test
	void unknownMetadataRefusesOnlyOptionalCachingWithoutInvokingIt() {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 64 * 1024L);
		AtomicInteger computations = new AtomicInteger();
		AtomicInteger calls = new AtomicInteger();
		Supplier<String> opaque = () -> {
			calls.incrementAndGet();
			return "never-call";
		};
		var context = context();
		try {
			Supplier<TupleExpr> computer = () -> {
				computations.incrementAndGet();
				QueryRoot result = planned();
				result.setQueryModelMetadata("unknown.semantic.extension", opaque);
				return result;
			};
			cache.getOrCompute(new QueryRoot(pattern()), context, context::revision, computer);
			assertFalse(cache.getOrCompute(new QueryRoot(pattern()), context, context::revision, computer).cacheHit());
			assertEquals(2, computations.get());
			assertEquals(0, calls.get());
			assertEquals(0, cache.entryCount());
		} finally {
			cache.close();
		}
	}

	@Test
	void dataOnlyDeferredMetricKeepsSmallHitsAndChargesItsFutureLargeOutput() {
		var context = context();
		for (boolean large : new boolean[] { false, true }) {
			LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 64 * 1024L);
			AtomicInteger computations = new AtomicInteger();
			String payload = large ? "Ā".repeat(64 * 1024) : "small";
			try {
				Supplier<TupleExpr> computer = () -> {
					computations.incrementAndGet();
					QueryRoot result = planned();
					var diagnostic = OwnedStringDiagnostic.builder().append("owned:").jsonString(payload).build();
					result.setStringMetricPlannedDeferred("json-one", diagnostic);
					result.setStringMetricPlannedDeferred("json-two", diagnostic);
					return result;
				};
				cache.getOrCompute(new QueryRoot(pattern()), context, context::revision, computer);
				var next = cache.getOrCompute(new QueryRoot(pattern()), context, context::revision, computer);
				assertEquals(!large, next.cacheHit());
				assertEquals(large ? 2 : 1, computations.get());
				if (!large) {
					String one = next.plan().getStringMetricPlanned("json-one");
					assertSame(one, next.plan().getStringMetricPlanned("json-two"));
					assertEquals("owned:\"small\"", one);
				} else {
					assertEquals(0, cache.entryCount());
					assertEquals(0L, cache.retainedBytes());
				}
			} finally {
				cache.close();
			}
		}
	}

	@Test
	void deepReadyBindingUsesExactIterativeIdentityButNoRecursiveOptionalValueFact() {
		Value value = VF.createLiteral("leaf");
		Resource subject = VF.createIRI("urn:owned:s");
		for (int depth = 0; depth < 50_000; depth++) {
			value = VF.createTripleTerm(subject, P, value);
		}
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("deep", value);
		var identity = LmdbPipelinePlanCache.BindingIdentity.of(bindings);
		assertNotNull(identity);
		assertEquals(identity, LmdbPipelinePlanCache.BindingIdentity.of(bindings));
		InputBindingContext frame = LmdbCascadesOptimizer.detachedRootInput(identity, Set.of("deep"));
		assertEquals(InputBindingContext.fromAssuredBindingNames(Set.of("deep")), frame);
		Value emitted = identity.values().get(0).value();
		int depth = 0;
		while (emitted instanceof TripleTerm triple) {
			emitted = triple.getObject();
			depth++;
		}
		assertEquals(50_000, depth);
		assertEquals(VF.createLiteral("leaf"), emitted);
	}

	@Test
	void actualPackedPipelineKeepsARealWarmHitAndSchemaTwoDiagnostics(@TempDir Path directory) {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			IRI subject = VF.createIRI("urn:owned:s");
			IRI q = VF.createIRI("urn:owned:q");
			connection.add(subject, P, VF.createLiteral("left"));
			connection.add(subject, q, VF.createLiteral("right"));
			var query = connection
					.prepareTupleQuery("SELECT ?o ?other WHERE { ?s <urn:owned:p> ?o . ?s <urn:owned:q> ?other }");
			try (var rows = query.evaluate()) {
				assertTrue(rows.hasNext());
				BindingSet row = rows.next();
				assertEquals(VF.createLiteral("left"), row.getValue("o"));
				assertEquals(VF.createLiteral("right"), row.getValue("other"));
				assertFalse(rows.hasNext());
			}
			query.explain(Explanation.Level.Optimized);
			TupleExpr plan = (TupleExpr) query.explain(Explanation.Level.Optimized).tupleExpr();
			assertEquals("true", plan.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
			String json = plan.getStringMetricPlanned("optimizer.packedExplanationJson");
			assertNotNull(json);
			assertTrue(json.contains("\"schema\":2"));
			assertNotNull(plan.getStringMetricPlanned("optimizer.packedExplanation"));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void equalRoutingHashesCannotBorrowAnotherCompleteDatasetOrBindingIdentity() {
		var goal = OptimizationGoal.root();
		var firstDataset = new SimpleDataset();
		var secondDataset = new SimpleDataset();
		firstDataset.addDefaultGraph(VF.createIRI("urn:owned:Aa"));
		secondDataset.addDefaultGraph(VF.createIRI("urn:owned:BB"));
		MapBindingSet first = new MapBindingSet();
		first.addBinding("v", VF.createLiteral("Aa"));
		MapBindingSet second = new MapBindingSet();
		second.addBinding("v", VF.createLiteral("BB"));
		var a = LmdbCascadesOptimizer.cacheContext(firstDataset, first, goal, null, null, null);
		var b = LmdbCascadesOptimizer.cacheContext(secondDataset, second, goal, null, null, null);
		assertNotNull(a);
		assertNotNull(b);
		assertEquals(a.datasetFingerprint(), b.datasetFingerprint(), "actual Java String collision premise");
		assertEquals(a.parameterVariant(), b.parameterVariant());
		assertFalse(a.equals(b), "the actual full provider context must authenticate beyond routing hashes");
		var cache = new PackedPlanCache(8, 1);
		var initial = PackedCascadesPlanner.optimize(
				new QueryRoot(pattern()), goal, cache, a);
		var changed = PackedCascadesPlanner.optimize(
				new QueryRoot(pattern()), goal, cache, b);
		var repeated = PackedCascadesPlanner.optimize(
				new QueryRoot(pattern()), goal, cache, b);
		assertFalse(initial.metrics().planCacheHit());
		assertFalse(changed.metrics().planCacheHit());
		assertTrue(repeated.metrics().planCacheHit(),
				"matching complete ready inputs still reuse the real packed cache");
	}

