	private static StatementPattern pattern() {
		return new StatementPattern(new Var("s"), Var.of("p", P), new Var("o"));
	}

	private static QueryRoot planned() {
		QueryRoot result = new QueryRoot(pattern());
		result.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		return result;
	}

	private static LmdbPipelinePlanCache.Context context() {
		var revision = new LmdbPipelinePlanCache.Revision(new LmdbEstimatorRuntime.PlanningRevisions(17L, 2L, 3L, 4L),
				true);
		return new LmdbPipelinePlanCache.Context(revision, false, 0L, LmdbPipelinePlanCache.DatasetIdentity.of(null),
				LmdbPipelinePlanCache.BindingIdentity.of(EmptyBindingSet.getInstance()), "", false, false, false,
				"STANDARD", false);
	}
